"""Exercise typed 2D image atomics generated by the native DXIL compiler."""
from pathlib import Path
import subprocess
import sys
import tempfile

from native_direct_container_check import compute, words
from native_dpp_mirror_check import vop2
from native_scalar_lds_check import sop1
from startup_compute_dispatch_check import lines
from startup_compute_dispatch_texture_check import clean, run as run_consumer
from startup_compute_image_store_d16_check import RSRC2
from startup_compute_request_check import DATA, prepare
from startup_compute_translate_check import state_a
from startup_gfx2hlsl_compute_check import root_blob


OPS = {'add': 17, 'umax': 23, 'cmpswap': 16}
OPERAND = 0x80000011
COMPARE = 0x00000020
UINT_MASK = 0xffffffff
WIDTH = 32
TEXELS = 336  # 32x8, 16x4, and 8x2 in the shared texture-store runner.
FORMATS = {'add': 1 << 25, 'umax': 1 << 27, 'cmpswap': 1 << 29}


def image_atomic(op, *, coord=8, data=14, resource=8, flags=0, mask=None, dim=1, addr_flags=0):
    mask = (3 if op == 'cmpswap' else 1) if mask is None else mask
    return [0xF0000000 | OPS[op] << 18 | flags | mask << 8 | dim << 3,
            (resource // 4) << 16 | data << 8 | coord | addr_flags]


def program_words(op, *, returning=False, drop_glc=False, sparse=False, contend=False, resource=8, **encoding):
    # s[0:1] points to a table. Read one complete image descriptor into s[8:15].
    code = [0xBE810380, 0xF40C0200, 0xFA000000, 0xBF8CC07F]
    if contend:
        code += [0x7E100285, 0x7E120286]
    else:
        code += [vop2(0x1b, 8, 135, 0), vop2(0x16, 9, 131, 0),
                 vop2(0x25, 8, 130, 8), vop2(0x25, 9, 129, 9)]
    code += [0x7E1C02FF, 1 if contend else OPERAND]
    if op == 'cmpswap':
        code += [0x7E1E02FF, COMPARE]
    if sparse:
        code += [sop1(3, 126, 255), 0x55555555]
    flags = encoding.pop('flags', 0) | (0x2000 if returning and not drop_glc else 0)
    code += image_atomic(op, flags=flags, resource=resource, **encoding)
    if returning:
        # Use the returned old value as the data of a second write. Its
        # destination is disjoint from the first, so each lane has an oracle.
        code += [0xBF8C3F70, vop2(0x25, 8, 140, 8), *image_atomic('add', resource=resource)]
    code += [0xBBFD0000, 0xBF810000]
    return code


def compile_shader(cli, sdk, work, op, **options):
    source = work / f'{op}.cs'
    shader = source.with_suffix('.cso')
    shader.unlink(missing_ok=True)
    source.write_bytes(compute(words(*program_words(op, **options)), table=True))
    result = subprocess.run([cli, sdk, work / 'cache', 'gfx1013-container-cs', source, shader],
                            capture_output=True, text=True, timeout=30)
    return shader, result


def controls(cli, sdk, work):
    for op in OPS:
        shader, run = compile_shader(cli, sdk, work, op, returning=True)
        assert run.returncode == 0, (op, run.stdout, run.stderr)
        dump = subprocess.run([Path(sdk) / 'dxc.exe', '-dumpbin', shader],
                              capture_output=True, text=True, timeout=30, check=True).stdout
        operation = ('@dx.op.atomicCompareExchange.i32(i32 79,' if op == 'cmpswap'
                     else '@dx.op.atomicBinOp.i32(i32 78,')
        assert operation in dump and '2d' in dump, dump
        for options in ({'dim': 5}, {'mask': 15}, {'coord': 255}, {'flags': 0x80},
                        {'addr_flags': 0x40000000}, {'addr_flags': 0x200000},
                        *(({'data': 255},) if op == 'cmpswap' else ())):
            _, run = compile_shader(cli, sdk, work, op, **options)
            assert run.returncode and 'unsupported typed 2D image atomic operands' in run.stderr, (
                op, options, run.stdout, run.stderr)
    print('Typed image atomics compiled and unsupported dimensions, operands and modifiers were refused')


def reference(op, *, returning=False, sparse=False, contend=False):
    initial = [0x10f00000 + i for i in range(TEXELS)]
    for lane in range(32):
        x, y = 2 + lane % 8, 1 + lane // 8
        initial[y * WIDTH + x] = (COMPARE, 0x7ffffff0, 0xfffffff0, OPERAND)[lane % 4]
    expected = initial.copy()
    for lane in range(32):
        if sparse and lane % 2:
            continue
        x, y = (5, 6) if contend else (2 + lane % 8, 1 + lane // 8)
        index = y * WIDTH + x
        previous = expected[index]
        if op == 'add':
            expected[index] = (previous + (1 if contend else OPERAND)) & UINT_MASK
        elif op == 'umax':
            expected[index] = max(previous, OPERAND)
        elif previous == COMPARE:
            expected[index] = OPERAND
        if returning:
            probe = index + 12
            expected[probe] = (initial[probe] + previous) & UINT_MASK
    return initial, expected


def render(renderer, adapter, *args):
    run = subprocess.run([renderer, adapter, *args], capture_output=True, text=True, timeout=30)
    if run.returncode == 77:
        print(run.stdout + run.stderr, end='')
        raise SystemExit(77)
    return run


def hardware(cli, sdk, work, renderer, adapter):
    wave = render(renderer, adapter, '--shader-wave32')
    assert wave.returncode == 0, (wave.stdout, wave.stderr)
    print(wave.stdout, end='')
    for op, cases in (
        ('add', ({}, {'sparse': True, 'contend': True}, {'returning': True})),
        ('umax', ({}, {'returning': True, 'sparse': True})),
        ('cmpswap', ({}, {'returning': True, 'sparse': True})),
    ):
        for options in cases:
            shader, run = compile_shader(cli, sdk, work, op, **options)
            assert run.returncode == 0, (op, options, run.stdout, run.stderr)
            initial, expected = reference(op, **options)
            payload = work / 'texture.bin'
            payload.write_bytes(words(1 | FORMATS[op], 0, *initial, *expected))
            run = render(renderer, adapter, '--compute-texture-store-case', shader, payload)
            assert run.returncode == 0, (op, options, run.stdout, run.stderr)
            if 'debug_layer=enabled' in run.stdout:
                assert 'debug_errors=0 debug_warnings=0' in run.stdout, run.stdout
            print(f'{op} {options}: {TEXELS} texture words matched')
            if options.get('returning'):
                # Same guest instruction without GLC cannot produce the old word.
                mutant, result = compile_shader(cli, sdk, work, op, drop_glc=True, **options)
                assert result.returncode == 0, (result.stdout, result.stderr)
                rejected = render(renderer, adapter, '--compute-texture-store-case', mutant, payload)
                assert rejected.returncode == 1 and 'mip=0' in rejected.stderr, (
                    op, options, rejected.stdout, rejected.stderr)
                print(f'{op} with GLC cleared: {rejected.stderr.strip()}')


def runtime(cli, sdk, work, renderer, consumer, adapter):
    wave = render(renderer, adapter, '--shader-wave32')
    assert wave.returncode == 0, (wave.stdout, wave.stderr)
    print(wave.stdout, end='')
    cache, env = prepare(work)
    env.update(X2W_D3D12_LIST_NOOP='1', X2W_D3D12_DEBUG='1', X2W_TEST_DISPATCH_HARDWARE='1')
    env.pop('X2W_NATIVE_SHADERS', None)
    root = work / 'compute_root'
    root.write_bytes(root_blob(3, table_range=True))
    env['X2W_TEST_COMPUTE_ROOT'] = str(root)
    code = program_words('add', sparse=True, contend=True, resource=24)
    # Slot 67 supplies the table at s7. The consumer writes the texture view
    # at table byte 64, following the three root constants.
    code[:3] = [0xBE8C0307, 0xBE8D0380, 0xF40C0606, 0xFA000040]
    (work / 'program').write_bytes(words(*code))
    (work / 'data').write_bytes(DATA)
    (work / 'state').write_bytes(state_a((32, 1, 1), RSRC2))

    initial = [0x10f00000 + i for i in range(WIDTH * 8)]
    expected = initial.copy()
    expected[6 * WIDTH + 5] += 32  # 16 active lanes per group, two groups.
    got, result = run_consumer(work, consumer, env, 'texture-store-atomic', '<256I')
    assert got == initial and lines(result, 'refused: no translation'), result.stderr[-3000:]
    requests = lines(result, 'x2w-draw compute request')
    assert len(requests) == 1, result.stderr[-3000:]
    key = requests[0].split()[3]

    compiled = subprocess.run([cli, sdk, work / 'compiler-cache', 'gfx1013-direct-cs@0',
                               '--requests', cache, cache], capture_output=True, text=True, timeout=30)
    manifest = cache / f'{key}.txt'
    assert compiled.returncode == 0 and manifest.is_file(), (compiled.stdout, compiled.stderr)
    assert 'uav 0 tex2d uint table 1 64 channels 1' in manifest.read_text().splitlines()
    got, result = run_consumer(work, consumer, env, 'texture-store-atomic', '<256I')
    wrong = next((i for i, pair in enumerate(zip(got, expected, strict=True)) if pair[0] != pair[1]), None)
    assert wrong is None, (wrong, got[wrong], expected[wrong], result.stderr[-3000:])
    assert lines(result, 'Dispatch(2, 1, 1) translated'), result.stderr[-3000:]
    layer = clean(result)
    got, result = run_consumer(work, consumer, env, 'texture-store', '<1024H')
    assert got == [0x5000 + i for i in range(1024)], result.stderr[-3000:]
    assert lines(result, 'refused: an image atomic requires an R32_UINT UAV'), result.stderr[-3000:]
    print(f'Published DXIL matched all 256 words and the float UAV stayed unchanged; debug layer {layer}')


if __name__ == '__main__':
    mode, cli, sdk, *args = sys.argv[1:]
    with tempfile.TemporaryDirectory() as temp:
        {'controls': controls, 'hardware': hardware, 'runtime': runtime}[mode](cli, sdk, Path(temp), *args)
